{"packet_id":"D048-01","doc_id":"D048","jurisdiction":"MA","category":"rent_increase_limits","lifecycle":"enacted","title":"Massachusetts ban on local rent control (Chapter 40P)","requirement":"No city or town may enact, maintain or enforce rent control of any kind. Only a city or town that accepts this chapter may adopt rent control regulation, and six months after adoption owner compliance becomes entirely voluntary and uncoerced.","key_value":null,"coverage_conditions":"All cities and towns. A city or town that accepts this chapter may regulate only units owned by persons owning ten or more rental units and with fair market rent of $400 or less.","applicability":{"conditions":[{"type":"owner","role":"exempt","who":"person or entity owning fewer than ten rental units","unit_limit":null},{"type":"other","text":"rent control regulation may not apply to any rental unit with a fair market rent exceeding $400"}],"per_tenancy":"Applies only in a city or town that accepts this chapter and adopts rent control regulation.","coverage_quotes":["(b) such regulation may not include the regulation of occupancy, services, evictions, condominium conversion or the removal of properties from such regulation, nor may such regulation apply to any rental unit that is owned by a person or entity owning less than ten rental units or that has a fair market rent exceeding $400;"]},"exemptions":"Local rent control only where a city or town accepts this chapter; it may not cover units owned by a person owning fewer than ten rental units or units with fair market rent over $400, nor regulate occupancy, services, evictions or condominium conversion.","penalty":null,"effective_date":null,"valid_through":null,"citation":"G.L. c. 40P, § 4","quoted_span":"No city or town may enact, maintain or enforce rent control of any kind, except that any city or town that accepts this chapter may adopt rent control regulation that provides:","interaction":"Local rent control is permitted only for a city or town that accepts this chapter, and only on the terms listed.","relations":[{"type":"preempts_local","quote":"No city or town may enact, maintain or enforce rent control of any kind, except that any city or town that accepts this chapter may adopt rent control regulation that provides:"}],"confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D048-01","doc_id":"D048","jurisdiction":"MA","category":"just_cause_eviction","lifecycle":"enacted","title":"Massachusetts limit on local rent control regulation of evictions","requirement":"Rent control regulation adopted by a city or town that accepts this chapter may not include the regulation of occupancy, services, evictions, condominium conversion or the removal of properties from the regulation.","key_value":null,"coverage_conditions":"Rent control regulation adopted by a city or town that accepts this chapter; the limit is stated in subsection (b) of the section.","applicability":{"conditions":[],"per_tenancy":"Applies only where a city or town has accepted this chapter and adopted rent control regulation.","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"G.L. c. 40P, § 4","quoted_span":"(b) such regulation may not include the regulation of occupancy, services, evictions, condominium conversion or the removal of properties from such regulation, nor may such regulation apply to any rental unit that is owned by a person or entity owning less than ten rental units or that has a fair market rent exceeding $400;","interaction":null,"relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
